problems.solution:
import numpy as np

def sampling_probs(logits, temperature=1.0, top_k=None):
    z = np.asarray(logits, dtype=float)
    z = z / temperature
    if top_k is not None:
        kth = np.sort(z)[-top_k]
        z = np.where(z < kth, -np.inf, z)
    e = np.exp(z - z.max())
    return e / e.sum()

